-- ============================================================
-- بيانات تجريبية أولية (Seed data) - نفس بيانات العرض التوضيحي
-- نفّذ هذا الملف بعد schema.sql (مرة وحدة فقط)
-- ============================================================

on conflict (id) do nothing;

on conflict (id) do nothing;






on conflict (id) do update set
  name = excluded.name, slogan = excluded.slogan, description = excluded.description,
  address = excluded.address, city = excluded.city, phone = excluded.phone,
  whatsapp = excluded.whatsapp, email = excluded.email, "mapUrl" = excluded."mapUrl",
  "mapLink" = excluded."mapLink", "logoInitial" = excluded."logoInitial",
  "openingHours" = excluded."openingHours", images = excluded.images, socials = excluded.socials;
