insert into public.health_guides ("categoryId", active, title, cover, intro, "keyPoints", tips) values
  ('gc-diabetes', true, '{"ar":"أساسيات التغذية لمرضى السكري","fr":"Bases de la nutrition pour les diabétiques","en":"Nutrition basics for diabetics"}'::jsonb, 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800&q=80', '{"ar":"التغذية السليمة عنصر أساسي في ضبط مستوى السكر في الدم والحفاظ على الطاقة طوال اليوم.","fr":"Une alimentation adaptée est essentielle pour contrôler la glycémie et maintenir votre énergie.","en":"Proper nutrition is essential for controlling blood sugar and maintaining energy throughout the day."}'::jsonb, '{"ar":["اختر الكربوهيدرات المعقدة بدل البسيطة","وزّع وجباتك على مدار اليوم","راقب كمية السكريات المضافة"],"fr":["Préférez les glucides complexes","Répartissez vos repas dans la journée","Surveillez les sucres ajoutés"],"en":["Choose complex carbs over simple ones","Spread meals throughout the day","Watch added sugar intake"]}'::jsonb, '{"ar":["ابدأ وجباتك بالخضروات","تجنب المشروبات الغازية السكرية","مارس نشاطًا بدنيًا خفيفًا بعد الأكل"],"fr":["Commencez vos repas par des légumes","Évitez les sodas sucrés","Marchez un peu après les repas"],"en":["Start meals with vegetables","Avoid sugary sodas","Take a short walk after meals"]}'::jsonb),
  ('gc-diabetes', true, '{"ar":"قراءة الملصقات الغذائية لمرضى السكري","fr":"Lire les étiquettes alimentaires","en":"Reading food labels for diabetics"}'::jsonb, 'https://images.unsplash.com/photo-1580983230786-315dfb9c8c31?w=800&q=80', '{"ar":"معرفة كيفية قراءة الملصقات الغذائية يساعدك على اختيار المنتجات الأنسب.","fr":"Savoir lire les étiquettes vous aide à choisir les produits les plus adaptés.","en":"Knowing how to read food labels helps you choose the most suitable products."}'::jsonb, '{"ar":["انتبه لكمية السكريات لكل 100 غرام","تحقق من الألياف الغذائية","راقب حجم الحصة الموصى بها"],"fr":["Vérifiez les sucres pour 100g","Regardez les fibres alimentaires","Notez la portion recommandée"],"en":["Check sugars per 100g","Look at dietary fiber","Note the recommended serving size"]}'::jsonb, '{"ar":["قارن بين منتجات مشابهة قبل الشراء","ابحث عن عبارة \"بدون سكر مضاف\""],"fr":["Comparez des produits similaires avant d''acheter","Recherchez la mention \"sans sucre ajouté\""],"en":["Compare similar products before buying","Look for \"no added sugar\" labels"]}'::jsonb),
  ('gc-hypertension', true, '{"ar":"تقليل الملح في نظامك الغذائي","fr":"Réduire le sel dans votre alimentation","en":"Reducing salt in your diet"}'::jsonb, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=800&q=80', '{"ar":"تقليل استهلاك الملح يساهم بشكل مباشر في ضبط ضغط الدم.","fr":"Réduire le sel contribue directement à contrôler votre tension artérielle.","en":"Reducing salt intake directly helps control blood pressure."}'::jsonb, '{"ar":["تجنب الأطعمة المصنعة الغنية بالملح","استبدل الملح بالأعشاب والتوابل","اقرأ نسبة الصوديوم على الملصقات"],"fr":["Évitez les aliments transformés riches en sel","Remplacez le sel par des herbes","Lisez la teneur en sodium"],"en":["Avoid processed foods high in salt","Replace salt with herbs and spices","Read sodium content on labels"]}'::jsonb, '{"ar":["قلّل الملح تدريجيًا لتعتاد ذائقتك","تجنب المخللات والمقبلات الجاهزة"],"fr":["Réduisez le sel progressivement","Évitez les conserves et apéritifs salés"],"en":["Reduce salt gradually to adjust your taste","Avoid pickles and ready-made salty snacks"]}'::jsonb),
  ('gc-hypertension', true, '{"ar":"النشاط البدني وضغط الدم","fr":"Activité physique et tension artérielle","en":"Physical activity and blood pressure"}'::jsonb, 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&q=80', '{"ar":"ممارسة الرياضة بانتظام تساعد على خفض ضغط الدم بشكل طبيعي.","fr":"L''exercice régulier aide à réduire naturellement la tension artérielle.","en":"Regular exercise naturally helps lower blood pressure."}'::jsonb, '{"ar":["30 دقيقة مشي يوميًا كافية للبدء","اختر نشاطًا تستمتع به لتستمر عليه","استشر طبيبك قبل بدء نشاط مكثف"],"fr":["30 minutes de marche par jour suffisent","Choisissez une activité que vous aimez","Consultez avant une activité intense"],"en":["30 minutes of walking daily is a good start","Choose an activity you enjoy","Consult before intense activity"]}'::jsonb, '{"ar":["ابدأ بخطوات صغيرة وزد تدريجيًا","مارس النشاط في نفس الوقت يوميًا لتكوين عادة"],"fr":["Commencez petit et augmentez progressivement","Pratiquez à heure fixe pour créer une habitude"],"en":["Start small and increase gradually","Exercise at the same time daily to build a habit"]}'::jsonb),
  ('gc-cholesterol', true, '{"ar":"الدهون المشبعة وتأثيرها","fr":"Les graisses saturées et leur impact","en":"Saturated fats and their impact"}'::jsonb, 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800&q=80', '{"ar":"تقليل الدهون المشبعة يساعد في الحفاظ على مستوى كوليسترول صحي.","fr":"Réduire les graisses saturées aide à maintenir un taux de cholestérol sain.","en":"Reducing saturated fats helps maintain a healthy cholesterol level."}'::jsonb, '{"ar":["قلّل اللحوم الدهنية والزبدة","اختر منتجات ألبان قليلة الدسم","استبدل القلي بالشوي أو الطهي بالبخار"],"fr":["Réduisez viandes grasses et beurre","Choisissez des laitages allégés","Préférez grillé ou vapeur à la friture"],"en":["Reduce fatty meats and butter","Choose low-fat dairy products","Prefer grilling or steaming over frying"]}'::jsonb, '{"ar":["أضف الأفوكادو وزيت الزيتون كدهون صحية","اقرأ نسبة الدهون المشبعة على الملصقات"],"fr":["Ajoutez avocat et huile d''olive","Lisez la teneur en graisses saturées"],"en":["Add avocado and olive oil as healthy fats","Read saturated fat content on labels"]}'::jsonb),
  ('gc-cholesterol', true, '{"ar":"دور الألياف في خفض الكوليسترول","fr":"Le rôle des fibres","en":"The role of fiber"}'::jsonb, 'https://images.unsplash.com/photo-1580983230786-315dfb9c8c31?w=800&q=80', '{"ar":"الألياف الغذائية تساهم في خفض الكوليسترول الضار بشكل طبيعي.","fr":"Les fibres alimentaires aident à réduire naturellement le mauvais cholestérol.","en":"Dietary fiber naturally helps reduce bad cholesterol."}'::jsonb, '{"ar":["تناول الشوفان والبقوليات بانتظام","أكثر من الخضروات والفواكه الطازجة","اختر الخبز والحبوب الكاملة"],"fr":["Consommez avoine et légumineuses","Mangez plus de fruits et légumes frais","Choisissez pain et céréales complètes"],"en":["Eat oats and legumes regularly","Eat more fresh fruits and vegetables","Choose whole grain bread and cereals"]}'::jsonb, '{"ar":["ابدأ يومك بوجبة شوفان","أضف بذور الشيا أو الكتان لوجباتك"],"fr":["Commencez la journée avec de l''avoine","Ajoutez des graines de chia ou de lin"],"en":["Start your day with an oat meal","Add chia or flax seeds to your meals"]}'::jsonb),
  ('gc-weight', true, '{"ar":"تنظيم أحجام الحصص الغذائية","fr":"Gérer la taille des portions","en":"Managing portion sizes"}'::jsonb, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=800&q=80', '{"ar":"التحكم في حجم الحصص يساعد على إدارة الوزن دون الحاجة لحرمان شديد.","fr":"Contrôler les portions aide à gérer le poids sans privation excessive.","en":"Controlling portion sizes helps manage weight without excessive restriction."}'::jsonb, '{"ar":["استخدم أطباقًا أصغر حجمًا","تناول الطعام ببطء وانتبه لإشارات الشبع","تجنب الأكل أمام الشاشات"],"fr":["Utilisez des assiettes plus petites","Mangez lentement en écoutant votre satiété","Évitez de manger devant un écran"],"en":["Use smaller plates","Eat slowly and notice fullness cues","Avoid eating in front of screens"]}'::jsonb, '{"ar":["اشرب كوب ماء قبل الوجبة","خطط لوجباتك مسبقًا لتفادي الأكل العشوائي"],"fr":["Buvez un verre d''eau avant le repas","Planifiez vos repas à l''avance"],"en":["Drink a glass of water before meals","Plan your meals ahead to avoid random snacking"]}'::jsonb),
  ('gc-weight', true, '{"ar":"المشروبات وتأثيرها على الوزن","fr":"Les boissons et leur impact sur le poids","en":"Drinks and their impact on weight"}'::jsonb, 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=800&q=80', '{"ar":"السعرات الحرارية الخفية في المشروبات كثيرًا ما تُهمَل رغم تأثيرها الكبير.","fr":"Les calories cachées dans les boissons sont souvent négligées.","en":"Hidden calories in drinks are often overlooked despite their impact."}'::jsonb, '{"ar":["استبدل المشروبات الغازية بالماء","قلّل السكر في القهوة والشاي","انتبه لسعرات العصائر الصناعية"],"fr":["Remplacez les sodas par de l''eau","Réduisez le sucre dans le café et thé","Attention aux jus industriels"],"en":["Replace sodas with water","Reduce sugar in coffee and tea","Watch calories in industrial juices"]}'::jsonb, '{"ar":["أضف شرائح ليمون أو نعناع للماء لتنويع الطعم","احمل زجاجة ماء معك خلال اليوم"],"fr":["Ajoutez citron ou menthe à votre eau","Gardez une bouteille d''eau sur vous"],"en":["Add lemon or mint slices to your water","Carry a water bottle with you during the day"]}'::jsonb);
